{"hypotheses": [
  {
    "name": "Profitability-Value Defensive Interaction",
    "mechanism": "Firms with high operating profitability (OperProf) and low market valuation (BM) are better able to weather market stress, while firms with high earnings surprise (EarningsSurprise) tend to overreact in risk-off regimes. Combining these provides a defensive composite with positive convexity in downturns.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OperProf"},
        {"weight": 1.0, "primitive": "BM"},
        {"weight": -0.5, "primitive": "EarningsSurprise"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "EarningsSurprise", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.85,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Low-Risk Quality-Momentum Blend",
    "mechanism": "Stocks with high earnings consistency (EarningsConsistency) and low idiosyncratic volatility (IdioVol3F) outperform, while combining with industry momentum (IndMom) captures strong, persistent trends. The mix reduces adverse selection and enhances compounding.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "EarningsConsistency"},
        {"weight": -1.0, "primitive": "IdioVol3F"},
        {"weight": 0.5, "primitive": "IndMom"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "correlation", "primitive": "IndMom", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.70,
    "expected_decay_half_life_months": 48
  },
  {
    "name": "Capital Discipline under Loose Credit",
    "mechanism": "When the term spread is positive, disciplined capital allocation (low CompEquIss, low DebtIssuance) paired with high payout yield (NetPayoutYield) reflects prudent management that is rewarded when credit is easy and investors chase quality.",
    "expression": {
      "terms": [
        {"weight": -0.5, "primitive": "CompEquIss"},
        {"weight": -0.5, "primitive": "DebtIssuance"},
        {"weight": 1.0, "primitive": "NetPayoutYield"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.60,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Analyst Overreaction Correction",
    "mechanism": "Stocks with high analyst EPS forecast revisions (AnalystRevision) but high forecast dispersion (ForecastDispersion) and low earnings forecast to price (sfe) are prone to overreaction. Betting against this composite exploits reversal as initial excitement fades.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "AnalystRevision"},
        {"weight": 1.0, "primitive": "ForecastDispersion"},
        {"weight": -1.0, "primitive": "sfe"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.65,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Illiquidity-Driven Contrarian Alpha",
    "mechanism": "Illiquid stocks (Illiquidity) with low past returns (STreversal) and high payout yield (PayoutYield) embed higher risk premiums and behavioral mispricings, especially in risk-off regimes, producing contrarian gains as liquidity shocks mean revert.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "Illiquidity"},
        {"weight": 1.0, "primitive": "PayoutYield"},
        {"weight": 0.5, "primitive": "STreversal"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "correlation", "primitive": "Illiquidity", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Growth Skeptic Composite",
    "mechanism": "Stocks with high asset growth (AssetGrowth) and R&D investment (RD) but concurrent high share issuance (ShareIss1Y) are likely to be overvalued as they chase growth at the expense of shareholder returns, leading to medium-term underperformance.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "AssetGrowth"},
        {"weight": 0.5, "primitive": "RD"},
        {"weight": -1.0, "primitive": "ShareIss1Y"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "subperiod_consistency"},
      {"type": "international", "region": "emerging", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.60,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Market Microstructure-Momentum Synergy",
    "mechanism": "Stocks with low bid-ask spreads (BidAskSpread), high volume trends (VolumeTrend), and high residual momentum (ResidualMomentum) benefit from both structural liquidity and attention-driven underreaction, making positive returns more persistent and less costly to capture.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "BidAskSpread"},
        {"weight": 1.0, "primitive": "VolumeTrend"},
        {"weight": 1.0, "primitive": "ResidualMomentum"}
      ],
      "regime": null,
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "ResidualMomentum", "bound": "below", "threshold": 0.3},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.55,
    "expected_decay_half_life_months": 12
  },
  {
    "name": "Late Cycle Quality Rotation",
    "mechanism": "During periods when the market has risen over the last 12 months, rotating into firms with high organizational capital (OrgCap) and strong gross profits to assets (GP) but low total accruals (TotalAccruals) captures resilient quality as speculative excess peaks.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OrgCap"},
        {"weight": 1.0, "primitive": "GP"},
        {"weight": -0.5, "primitive": "TotalAccruals"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.80,
    "expected_decay_half_life_months": 36
  }
]}
